// 往 logs[owner][contact] 写一条（墓碑跳过、按内容去重、仅自己手机计未读）。返回是否有变化。
function putMsg(owner, contact, msg, countUnread) {
  if (!owner || !contact || isDeleted(owner, contact)) return false
  if (!logs.value[owner]) logs.value[owner] = {}
