  arr.push(msg)
  if (countUnread && msg.dir === '收到' && owner === meName.value && activeContact.value !== contact) {
    if (!unread.value[owner]) unread.value[owner] = {}
    unread.value[owner][contact] = (unread.value[owner][contact] || 0) + 1
