  const i = arr.findIndex(m => m.sid === pendingRef.sid)
  if (i < 0) { pendingRef = null; return }              // 那条已不在（被删/被去重合并）→ 松开引用
  if (arr.slice(i + 1).some(m => m.dir === '收到')) { markSent(pendingRef); pendingRef = null }
}

function send(retryText) {
